def load(path: Union[os.PathLike, str]) -> c.CDLL:
    """Load exactly the caller-selected shared library and declare every symbol."""
    library = c.CDLL(os.fspath(path))

    def declare(name: str, arguments: list[object], result: object, doc: str) -> None:
        function = getattr(library, name)
        function.argtypes = arguments
        function.restype = result
        function.__doc__ = doc

    declare("mimusb_last_error", [], c.POINTER(ErrorDetail), "The details of the calling thread's last result.")
    declare("mimusb_result_name", [c.c_int32], c.c_char_p, "The name of a result constant.")
    declare("mimusb_frame_type_name", [c.c_int32], c.c_char_p, "Names the serial frame type of mimusb_error_detail.frame_type (docs/PROTOCOL.md).")
    declare("mimusb_version", [], c.c_uint32, "The version of the library that is running.")
    declare("mimusb_discover", [c.c_uint32, c.POINTER(DiscoveryP)], c.c_int32, "Searches the serial ports for boards and returns a snapshot of them.")
    declare("mimusb_discovery_count", [DiscoveryP], c.c_size_t, "The number of boards in a snapshot.")
    declare("mimusb_discovery_get", [DiscoveryP, c.c_size_t], c.POINTER(DeviceInfo), "One board of a snapshot.")
    declare("mimusb_discovery_destroy", [DiscoveryP], None, "Frees a snapshot.")
    declare("mimusb_device_open", [c.c_char_p, c.POINTER(DeviceConfig), c.POINTER(DeviceP)], c.c_int32, "Opens a board on a serial port.")
    declare("mimusb_device_close", [DeviceP, c.c_uint32, c.c_uint32], c.c_int32, "Closes a Device and its Nodes.")
    declare("mimusb_device_set_usb_identity", [DeviceP, c.POINTER(UsbDevice), c.POINTER(UsbConfig), c.POINTER(CommitTimeouts)], c.c_int32, "Sets the USB device descriptor, configuration and strings the target sees.")
    declare("mimusb_device_latched_error", [DeviceP], c.c_int32, "Reads the error the reader thread recorded for the link, and forgets it unless it is MIMUSB_ERR_NO_DEVICE, which stays.")
    declare("mimusb_device_is_ready", [DeviceP], c.c_int32, "Whether the target has mounted the board's USB device.")
    declare("mimusb_device_wait_ready", [DeviceP, c.c_uint32], c.c_int32, "Waits until the target mounts the board's USB device.")
    declare("mimusb_device_batch_begin", [DeviceP], c.c_int32, "Starts gathering changes into one commit.")
    declare("mimusb_device_batch_end", [DeviceP, c.POINTER(CommitTimeouts)], c.c_int32, "Commits every change made since mimusb_device_batch_begin.")
    declare("mimusb_device_commit", [DeviceP, c.c_uint32, c.POINTER(CommitTimeouts)], c.c_int32, "Sends the configuration and makes the board enumerate again.")
    declare("mimusb_device_connect", [DeviceP, c.POINTER(CommitTimeouts)], c.c_int32, "Puts the board's USB device on the target.")
    declare("mimusb_device_disconnect", [DeviceP, c.c_uint32], c.c_int32, "Takes the board's USB device off the target.")
    declare("mimusb_device_remote_wakeup", [DeviceP, c.c_uint32], c.c_int32, "Wakes a target that suspended the board's USB device; the target must have enabled remote wakeup (usb_config.bm_attributes bit 5 and MIMUSB_EVENT_SUSPEND with value 1).")
    declare("mimusb_device_enter_bootloader", [DeviceP, c.c_uint32], c.c_int32, "Restarts the board into its chip's own bootloader, where new firmware is written.")
    declare("mimusb_device_board_info", [DeviceP, c.POINTER(DeviceInfo)], c.c_int32, "What the board reported at open.")
    declare("mimusb_device_limits", [DeviceP, c.POINTER(BoardLimits)], c.c_int32, "The limits of the board.")
    declare("mimusb_device_link_counters", [DeviceP, c.c_uint32, c.c_uint32, c.POINTER(LinkCounters)], c.c_int32, "With reset nonzero the board's counters are zeroed after being read.")
    declare("mimusb_device_set_control_rules", [DeviceP, c.c_uint32, c.POINTER(ControlRule), c.c_size_t, c.c_uint32], c.c_int32, "Replaces the Device's own rules, which come after those of the Nodes.")
    declare("mimusb_device_set_rule_data", [DeviceP, c.c_size_t, c.POINTER(c.c_uint8), c.c_size_t, c.c_uint32], c.c_int32, "Changes the bytes of ANSWER rule number rule_index of mimusb_device_set_control_rules, up to the length its data had when the rules were set.")
    declare("mimusb_node_set_rule_data", [NodeP, c.c_size_t, c.POINTER(c.c_uint8), c.c_size_t, c.c_uint32], c.c_int32, "As mimusb_device_set_rule_data for rule number rule_index of the Node's own rules: the extra_rules of its placement first, then the rules its Spec brings (mimusb_node_find_rule finds one the Spec names).")
    declare("mimusb_node_find_rule", [NodeP, c.c_int32, c.POINTER(c.c_size_t)], c.c_int32, "Finds the rule the Spec of a Node names with `slot` (mimusb_rule_slot) among the Node's own rules, so that mimusb_node_set_rule_data can change its bytes: *out_rule_index is its number, which counts the Node's extra_rules first (a Node has them before the rules of its Spec).")
    declare("mimusb_device_control_reply", [DeviceP, c.c_uint32, c.c_int32, c.POINTER(c.c_uint8), c.c_size_t, c.c_uint32], c.c_int32, "Answers the held transfer of token (from MIMUSB_EVENT_CONTROL_SETUP with the HELD flag, or from MIMUSB_EVENT_CONTROL_DATA for the verdict of a host-to-device transfer) with action: ANSWER (data is the data stage of a device-to-host request, empty otherwise, or the acknowledging verdict), STALL, DROP (data empty) or LEAVE (the board's own handling).")
    declare("mimusb_device_set_loss_reporting", [DeviceP, c.c_uint32, c.c_uint32, c.c_uint32], c.c_int32, "enabled 1 makes the board report the transfers it drops because a queue is full (MIMUSB_EVENT_TRANSFER_LOST), at most one event per interval_ms (0 to MIMUSB_LOSS_MAX_INTERVAL_MS; 0 reports each time).")
    declare("mimusb_device_add_string", [DeviceP, c.c_char_p, c.POINTER(c.c_uint8)], c.c_int32, "Stores a string descriptor (in the Device's language_id) and returns its index, for the caller's own class descriptors.")
    declare("mimusb_device_remove_string", [DeviceP, c.c_uint8], c.c_int32, "Forgets a string given by mimusb_device_add_string; the next commit no longer sends it.")
    declare("mimusb_device_set_string", [DeviceP, c.c_uint8, c.c_uint16, c.POINTER(c.c_uint16), c.c_size_t], c.c_int32, "Stores a string descriptor exactly as it goes on the bus: index 1 to 255, a nonzero language_id (USB 2.0 9.6.7) and unit_count UTF-16 code units (1 to 126).")
    declare("mimusb_device_clear_string", [DeviceP, c.c_uint8, c.c_uint16], c.c_int32, "Forgets a string given by mimusb_device_set_string; the next commit no longer sends it.")
    declare("mimusb_device_set_bos", [DeviceP, c.POINTER(c.c_uint8), c.c_size_t], c.c_int32, "For a Device composed from Nodes: stores the Binary Object Store descriptor (USB 3.2 9.6.2); length 0 removes it.")
    declare("mimusb_device_set_descriptors", [DeviceP, c.POINTER(DeviceDescriptors), c.POINTER(CommitTimeouts)], c.c_int32, "Presents the bytes unchanged; usb_device, usb_config and their strings are not used.")
    declare("mimusb_device_clear_descriptors", [DeviceP, c.POINTER(CommitTimeouts)], c.c_int32, "Forgets the descriptors, the policies of their endpoints and what the board held for them; Nodes can be opened again.")
    declare("mimusb_device_endpoint_set_policy", [DeviceP, c.c_uint8, c.POINTER(EndpointPolicy), c.c_uint32], c.c_int32, "The policy of an IN endpoint of a Device given as bytes.")
    declare("mimusb_device_endpoint_write", [DeviceP, c.c_uint8, c.POINTER(c.c_uint8), c.c_size_t, c.c_uint32], c.c_int32, "As mimusb_node_endpoint_write, for an IN endpoint of a Device given as bytes.")
    declare("mimusb_device_endpoint_stall", [DeviceP, c.c_uint8, c.c_uint32], c.c_int32, "As mimusb_node_endpoint_stall for an endpoint of a Device given as bytes.")
    declare("mimusb_device_endpoint_clear_stall", [DeviceP, c.c_uint8, c.c_uint32], c.c_int32, "As mimusb_node_endpoint_clear_stall for an endpoint of a Device given as bytes.")
    declare("mimusb_device_endpoint_flush", [DeviceP, c.c_uint8, c.c_uint32], c.c_int32, "As mimusb_node_endpoint_flush for an IN endpoint of a Device given as bytes.")
    declare("mimusb_spec_create_keyboard", [c.POINTER(KeyboardOptions), c.POINTER(SpecP)], c.c_int32, "Makes a keyboard Spec.")
    declare("mimusb_spec_create_mouse", [c.POINTER(MouseOptions), c.POINTER(SpecP)], c.c_int32, "Makes a mouse Spec.")
    declare("mimusb_spec_create_toggle", [c.POINTER(ToggleOptions), c.POINTER(SpecP)], c.c_int32, "Makes a Spec of one-bit controls on a HUT page.")
    declare("mimusb_spec_create_gamepad", [c.POINTER(GamepadOptions), c.POINTER(SpecP)], c.c_int32, "Makes a gamepad Spec.")
    declare("mimusb_spec_create_touchscreen", [c.POINTER(TouchscreenOptions), c.POINTER(SpecP)], c.c_int32, "Makes a touchscreen Spec.")
    declare("mimusb_spec_create_touchpad", [c.POINTER(TouchpadOptions), c.POINTER(SpecP)], c.c_int32, "Makes a touchpad Spec.")
    declare("mimusb_spec_create_pen", [c.POINTER(PenOptions), c.POINTER(SpecP)], c.c_int32, "Makes a pen Spec.")
    declare("mimusb_spec_create_digitizer", [c.POINTER(DigitizerOptions), c.POINTER(SpecP)], c.c_int32, "Makes a digitizer Spec.")
    declare("mimusb_spec_create_hid", [c.POINTER(HidOptions), c.POINTER(SpecP)], c.c_int32, "Makes a Spec from the caller's own HID report descriptor.")
    declare("mimusb_spec_create_cdc_acm", [c.POINTER(CdcAcmOptions), c.POINTER(SpecP)], c.c_int32, "Makes a Spec of a CDC-ACM function (see mimusb_cdc_acm_options): two interfaces and the roles MIMUSB_ROLE_CDC_NOTIFY (interrupt), MIMUSB_ROLE_CDC_DATA_IN and MIMUSB_ROLE_CDC_DATA_OUT (bulk), all required.")
    declare("mimusb_spec_create_interfaces", [c.POINTER(NodeConfig), c.POINTER(SpecP)], c.c_int32, "Makes a Spec of any class from interfaces written out.")
    declare("mimusb_spec_roles", [SpecP, c.POINTER(RoleInfo), c.c_size_t, c.POINTER(c.c_size_t)], c.c_int32, "Lists the endpoint roles of a Spec in order and whether each is required, so a caller sees what its placement must give.")
    declare("mimusb_spec_interface_count", [SpecP, c.POINTER(c.c_size_t)], c.c_int32, "The number of interfaces a Node of the Spec takes on the bus: 1 for a HID Spec, 2 for a CDC-ACM Spec, the length of the configuration for a Spec of mimusb_spec_create_interfaces.")
    declare("mimusb_spec_rule_cost", [SpecP, c.POINTER(c.c_size_t), c.POINTER(c.c_size_t)], c.c_int32, "What a Node of the Spec adds to the board's control rule memory, not counting the extra_rules of its placement: the number of rules and the bytes of their ANSWER data.")
    declare("mimusb_spec_retain", [SpecP], None, "Adds a reference to a Spec.")
    declare("mimusb_spec_release", [SpecP], None, "Gives up a reference to a Spec.")
    declare("mimusb_spec_descriptor", [SpecP, c.POINTER(c.POINTER(c.c_uint8)), c.POINTER(c.c_size_t)], c.c_int32, "The report descriptor of a Spec.")
    declare("mimusb_spec_manifest", [SpecP, c.POINTER(CapabilityManifest)], c.c_int32, "What a Spec sends.")
    declare("mimusb_node_open", [DeviceP, SpecP, c.POINTER(NodePlacement), c.POINTER(CommitTimeouts), c.POINTER(NodeP)], c.c_int32, "Opens a Node of any class: spec says what it is, placement says where it goes.")
    declare("mimusb_node_close", [NodeP, c.POINTER(CommitTimeouts), c.c_uint32], c.c_int32, "Closing a Node whose interface number is not the highest in use leaves a gap: the Node is gone, the commit fails with MIMUSB_ERR_PARAM, and a later commit succeeds once the gap is closed.")
    declare("mimusb_node_id", [NodeP], c.c_uint16, "The number the board knows a Node by.")
    declare("mimusb_node_set_feature_response", [NodeP, c.c_uint8, c.POINTER(c.c_uint8), c.c_size_t, c.c_uint32], c.c_int32, "Sets what the board answers (the bytes after the Report ID, at most max_feature_bytes) when the target reads Feature report report_id of this Node.")
